  1	import { Context, Effect, Schema } from "effect";
  2	
  3	import { CodexResponsesRequest } from "./contracts.js";
  4	import type {
  5	  CodexResponsesFunctionTool as CodexResponsesFunctionToolType,
  6	  CodexResponsesInput as CodexResponsesInputType,
  7	  CodexResponsesRequest as CodexResponsesRequestType,
  8	  CodexResponsesToolChoice as CodexResponsesToolChoiceType,
  9	  OpenAICompatibleChatCompletionRequest,
 10	} from "./contracts.js";
 11	import { CodexResponsesRequestError } from "./errors.js";
 12	import { CodexResponsesRequestPolicyService } from "./request-policy.js";
 13	
 14	export interface CodexRequestMapperShape {
 15	  readonly toCodexResponses: (
 16	    input: OpenAICompatibleChatCompletionRequest
 17	  ) => Effect.Effect<CodexResponsesRequestType, CodexResponsesRequestError>;
 18	}
 19	
 20	export class CodexRequestMapper extends Context.Service<
 21	  CodexRequestMapper,
 22	  CodexRequestMapperShape
 23	>()("@bundjil/codex/CodexRequestMapper") {}
 24	
 25	export const makeCodexRequestMapper = Effect.gen(
 26	  function* makeCodexRequestMapperService() {
 27	    const requestPolicy = yield* CodexResponsesRequestPolicyService;
 28	
 29	    return CodexRequestMapper.of({
 30	      toCodexResponses: Effect.fn("CodexRequestMapper.toCodexResponses")(
 31	        function* (input: OpenAICompatibleChatCompletionRequest) {
 32	          const instructionParts: string[] = [];
 33	          const responsesInput: CodexResponsesInputType[] = [];
 34	
 35	          for (const message of input.messages) {
 36	            if (message.role === "system") {
 37	              if (message.content.length > 0) {
 38	                instructionParts.push(message.content);
 39	              }
 40	              continue;
 41	            }
 42	
 43	            if (message.role === "user") {
 44	              if (message.content.length > 0) {
 45	                responsesInput.push({
 46	                  role: "user",
 47	                  content: [{ type: "input_text", text: message.content }],
 48	                });
 49	              }
 50	              continue;
 51	            }
 52	
 53	            if (message.role === "tool") {
 54	              responsesInput.push({
 55	                type: "function_call_output",
 56	                call_id: message.tool_call_id,
 57	                output: message.content,
 58	              });
 59	              continue;
 60	            }
 61	
 62	            if (
 63	              message.content !== undefined &&
 64	              message.content !== null &&
 65	              message.content.length > 0
 66	            ) {
 67	              responsesInput.push({
 68	                role: "assistant",
 69	                content: [{ type: "output_text", text: message.content }],
 70	              });
 71	            }
 72	
 73	            for (const toolCall of message.tool_calls ?? []) {
 74	              responsesInput.push({
 75	                type: "function_call",
 76	                call_id: toolCall.id,
 77	                name: toolCall.function.name,
 78	                arguments: toolCall.function.arguments,
 79	              });
 80	            }
 81	          }
 82	
 83	          const instructions = instructionParts.join("\n");
 84	          const tools: CodexResponsesFunctionToolType[] | undefined =
 85	            input.tools?.map((tool) => ({
 86	              type: "function",
 87	              name: tool.function.name,
 88	              ...(tool.function.description === undefined
 89	                ? {}
 90	                : { description: tool.function.description }),
 91	              parameters: tool.function.parameters,
 92	              ...(tool.function.strict === undefined
 93	                ? {}
 94	                : { strict: tool.function.strict }),
 95	            }));
 96	          const toolChoice: CodexResponsesToolChoiceType | undefined =
 97	            typeof input.tool_choice === "object"
 98	              ? { type: "function", name: input.tool_choice.function.name }
 99	              : input.tool_choice;
100	
101	          return yield* Schema.decodeUnknownEffect(CodexResponsesRequest)({
102	            model: input.model,
103	            input: responsesInput,
104	            store: false,
105	            ...(instructions.length === 0 ? {} : { instructions }),
106	            stream: input.stream ?? true,
107	            reasoning: { effort: requestPolicy.policy.reasoningEffort },
108	            ...(tools === undefined
109	              ? {}
110	              : { tools, parallel_tool_calls: false }),
111	            ...(toolChoice === undefined ? {} : { tool_choice: toolChoice }),
112	          }).pipe(
113	            Effect.mapError(
114	              () =>
115	                new CodexResponsesRequestError({
116	                  boundary: "CodexResponsesRequest",
117	                  message: "Unable to map OpenAI-compatible request to Codex.",
118	                })
119	            )
120	          );
121	        }
122	      ),
123	    });
124	  }
125	);
126	
127	export const toCodexResponses = Effect.fnUntraced(
128	  function* toCodexResponsesOperation(
129	    input: OpenAICompatibleChatCompletionRequest
130	  ) {
131	    const mapper = yield* CodexRequestMapper;
132	
133	    return yield* mapper.toCodexResponses(input);
134	  }
135	);
