 11	export type OpenAICompatibleProxyFailure =
 12	  | OpenAICompatibleProxyAuthError
 13	  | CodexDirectProviderFailure;
 14	
 15	export interface OpenAICompatibleProxyShape {
 16	  readonly handleChatCompletions: (
 17	    input: OpenAICompatibleProxyInput
 18	  ) => Effect.Effect<
 19	    OpenAICompatibleChatCompletionStream,
