 27	>()("@bundjil/codex/OpenAICompatibleProxy") {}
 28	
 29	export const makeOpenAICompatibleProxy = Effect.gen(
 30	  function* makeOpenAICompatibleProxyService() {
 31	    const directProvider = yield* CodexDirectProvider;
 32	
 33	    return OpenAICompatibleProxy.of({
 34	      handleChatCompletions: Effect.fn(
 35	        "OpenAICompatibleProxy.handleChatCompletions"
 36	      )(function* (input: OpenAICompatibleProxyInput) {
 37	        const expectedAuthorization = `Bearer ${Redacted.value(
