 43	            operation: "handleChatCompletions",
 44	            message: "Codex proxy request is not authorized.",
 45	          });
 46	        }
 47	
 48	        return yield* directProvider.streamChatCompletion(input.completion);
 49	      }),
 50	    });
 51	  }
 52	).pipe(Effect.withSpan("OpenAICompatibleProxyLive"));
 53	
 54	export const handleChatCompletions = Effect.fnUntraced(
 55	  function* handleChatCompletionsOperation(input: OpenAICompatibleProxyInput) {
 56	    const proxy = yield* OpenAICompatibleProxy;
 57	
 58	    return yield* proxy.handleChatCompletions(input);
