  6	import { Effect, Layer, Match, Schema } from "effect";
  7	import * as FileSystem from "effect/FileSystem";
  8	import {
  9	  HttpRouter,
 10	  HttpServerRequest,
 11	  HttpServerResponse,
 12	} from "effect/unstable/http";
 13	
 14	import { CodexProxyConfig, CodexProxyConfigLive } from "./env.js";
 15	import { CodexProxyRouteError } from "./errors.js";
 16	import { CodexProxyOpenAICompatibleProxyLiveOrUnavailable } from "./live.layer.js";
 17	import {
 18	  CodexProxyOpenAICompatibleProxyLocalUnavailableLive,
 19	  makeCodexProxyOpenAICompatibleProxyLocal,
 20	} from "./local.layer.js";
 21	import { CodexProxyOpenAICompatibleProxyMockLive } from "./mock.layer.js";
 22	import { CodexProxyReadiness } from "./readiness.service.js";
 23	import {
 24	  CodexProxyErrorResponse,
 25	  CodexProxyHealthResponse,
 26	  CodexProxyRequestContentLength,
 27	} from "./schemas.js";
 28	import type { CodexProxyErrorCode } from "./schemas.js";
 29	
 30	const healthJson = HttpServerResponse.schemaJson(CodexProxyHealthResponse);
 31	const errorJson = HttpServerResponse.schemaJson(CodexProxyErrorResponse);
 32	const codexProxyRequestBodyMaxBytes = FileSystem.Size(1024 * 1024);
 33	
 34	const errorResponse = (
 35	  code: CodexProxyErrorCode,
 36	  message: string,
 37	  status: number
 38	) =>
 39	  errorJson(
 40	    {
 41	      error: {
 42	        code,
 43	        message,
 44	      },
 45	    },
 46	    { status }
 47	  ).pipe(Effect.orDie);
 48	
 49	const reauthenticationRequiredResponse = errorResponse(
 50	  "codex_reauthentication_required",
 51	  "Codex authorization requires a new trusted-local login.",
 52	  502
 53	);
 54	
 55	const authTemporarilyUnavailableResponse = errorResponse(
 56	  "codex_auth_temporarily_unavailable",
 57	  "Codex authorization is temporarily unavailable.",
 58	  503
 59	);
 60	
 61	const healthRoute = Effect.gen(function* healthRoute() {
 62	  const config = yield* CodexProxyConfig;
 63	  const readiness = yield* CodexProxyReadiness;
 64	
 65	  return yield* healthJson(
 66	    {
 67	      mode: config.mode,
 68	      ok: readiness.ready,
 69	      reasoningEffort: config.reasoningEffort,
 70	      service: "bundjil-codex-proxy",
 71	    },
 72	    { status: readiness.ready ? 200 : 503 }
 73	  ).pipe(Effect.orDie);
 74	});
 75	
 76	const chatCompletionsRoute = (request: HttpServerRequest.HttpServerRequest) =>
 77	  Effect.gen(function* chatCompletionsRoute() {
 78	    const config = yield* CodexProxyConfig;
 79	    const declaredContentLength = request.headers["content-length"];
 80	
 81	    if (declaredContentLength !== undefined) {
 82	      const contentLength = yield* Schema.decodeUnknownEffect(
 83	        CodexProxyRequestContentLength
 84	      )(declaredContentLength).pipe(
 85	        Effect.mapError(
 86	          () =>
 87	            new CodexProxyRouteError({
 88	              boundary: "CodexProxyRequestContentLength",
 89	              code: "bad_request",
 90	              message: "Unable to decode Codex proxy request content length.",
 91	              responseMessage: "The request body could not be read.",
 92	              status: 400,
 93	            })
 94	        )
 95	      );
 96	
 97	      if (contentLength > codexProxyRequestBodyMaxBytes) {
 98	        return yield* new CodexProxyRouteError({
 99	          boundary: "CodexProxyRequestContentLength",
100	          code: "bad_request",
101	          message:
102	            "Codex proxy request body exceeded the configured byte limit.",
103	          responseMessage: "The request body could not be read.",
104	          status: 400,
105	        });
106	      }
107	    }
108	
109	    const body = yield* request.text.pipe(
110	      Effect.provideService(
111	        HttpServerRequest.MaxBodySize,
112	        codexProxyRequestBodyMaxBytes
113	      ),
114	      Effect.mapError(
115	        () =>
116	          new CodexProxyRouteError({
117	            code: "bad_request",
118	            message: "Unable to read Codex proxy request body.",
119	            responseMessage: "The request body could not be read.",
120	            status: 400,
121	          })
122	      )
123	    );
124	    const completion = yield* Schema.decodeUnknownEffect(
125	      Schema.fromJsonString(OpenAICompatibleChatCompletionRequest)
126	    )(body).pipe(
127	      Effect.mapError(
128	        () =>
129	          new CodexProxyRouteError({
130	            boundary: "OpenAICompatibleChatCompletionRequest",
131	            code: "bad_request",
132	            message:
133	              "Unable to decode OpenAI-compatible chat completion request.",
134	            responseMessage:
135	              "The request does not match the Codex proxy contract.",
136	            status: 400,
137	          })
138	      )
139	    );
140	    const proxyInput = yield* OpenAICompatibleProxyInput.makeEffect({
141	      ...(request.headers["authorization"] === undefined
142	        ? {}
143	        : { authorization: request.headers["authorization"] }),
144	      completion: {
145	        ...(config.accountId === undefined
