147	          : { accountId: config.accountId }),
148	        request: completion,
149	        subject: config.subject,
150	      },
151	      internalToken: config.internalToken,
152	    }).pipe(
153	      Effect.mapError(
154	        () =>
155	          new CodexProxyRouteError({
156	            boundary: "OpenAICompatibleProxyInput",
157	            code: "bad_request",
158	            message: "Unable to decode Codex proxy request envelope.",
159	            responseMessage:
160	              "The request does not match the Codex proxy contract.",
161	            status: 400,
162	          })
163	      )
164	    );
165	    const proxy = yield* OpenAICompatibleProxy;
166	    const stream = yield* proxy.handleChatCompletions(proxyInput);
167	
168	    return HttpServerResponse.stream(stream.body, {
169	      contentType: stream.contentType,
170	      headers: {
171	        "cache-control": "no-cache, no-transform",
172	        "x-accel-buffering": "no",
173	        "x-bundjil-codex-proxy-model-invocation": "true",
174	        "x-bundjil-codex-proxy-mode": config.mode,
175	      },
176	      status: 200,
177	    });
178	  }).pipe(
179	    Effect.catchTags({
180	      CodexProxyRouteError: (error) =>
181	        errorResponse(error.code, error.responseMessage, error.status),
182	      OpenAICompatibleProxyAuthError: () =>
183	        errorResponse("unauthorized", "Unauthorized.", 401),
184	      CodexResponsesRequestError: () =>
185	        errorResponse("proxy_error", "The proxy request failed.", 502),
186	      CodexHttpNetworkError: () =>
187	        errorResponse("proxy_error", "The proxy request failed.", 502),
188	      CodexHttpStatusError: () =>
189	        errorResponse("proxy_error", "The proxy request failed.", 502),
190	      CodexResponsesStreamError: () =>
191	        errorResponse("proxy_error", "The proxy stream failed.", 502),
192	      CodexProfileNotFound: () => reauthenticationRequiredResponse,
193	      CodexProfileSchemaError: () => reauthenticationRequiredResponse,
194	      CodexProfileStorageError: () => authTemporarilyUnavailableResponse,
195	      CodexOAuthTokenMissing: () => reauthenticationRequiredResponse,
196	      CodexOAuthTokenExpired: () => reauthenticationRequiredResponse,
197	      CodexOAuthOperationError: () => reauthenticationRequiredResponse,
198	      CodexReauthenticationRequired: () => reauthenticationRequiredResponse,
199	      CodexAuthTemporarilyUnavailable: () => authTemporarilyUnavailableResponse,
200	      CodexOAuthRefreshLockError: () => authTemporarilyUnavailableResponse,
201	      CodexSubscriptionAuthError: () => authTemporarilyUnavailableResponse,
202	      CodexOAuthProfileCommitConflict: () => authTemporarilyUnavailableResponse,
203	      CodexOAuthProfileCommitError: () => authTemporarilyUnavailableResponse,
204	      CodexOAuthProfileCipherError: () => reauthenticationRequiredResponse,
205	      CodexOAuthUnsupportedRuntimePath: () =>
206	        authTemporarilyUnavailableResponse,
207	    })
208	  );
209	
210	const notFoundRoute = errorResponse("not_found", "Not found.", 404);
211	
212	export const CodexProxyRoutesLive = Layer.effectDiscard(
213	  Effect.gen(function* registerCodexProxyRoutes() {
214	    const router = yield* HttpRouter.HttpRouter;
215	
216	    yield* router.add("GET", "/health", healthRoute);
217	    yield* router.add("POST", "/v1/chat/completions", chatCompletionsRoute);
218	    yield* router.add("*", "/*", notFoundRoute);
219	  })
220	);
221	
222	const makeCodexProxyModeLayer = (
223	  liveProxyLayer = CodexProxyOpenAICompatibleProxyLiveOrUnavailable,
224	  makeLocalProxyLayer = makeCodexProxyOpenAICompatibleProxyLocal
225	) =>
226	  Layer.unwrap(
227	    Effect.gen(function* makeCodexProxyModeLayer() {
228	      const config = yield* CodexProxyConfig;
229	
230	      return Match.value(config.mode).pipe(
231	        Match.when("mock", () => CodexProxyOpenAICompatibleProxyMockLive),
232	        Match.when("local", () => {
233	          if (config.localProfileStoreDirectory === undefined) {
234	            return CodexProxyOpenAICompatibleProxyLocalUnavailableLive;
235	          }
236	
237	          return makeLocalProxyLayer(config.localProfileStoreDirectory, {
238	            reasoningEffort: config.reasoningEffort,
239	          });
240	        }),
241	        Match.when("live", () => liveProxyLayer),
242	        Match.exhaustive
243	      );
244	    })
245	  );
246	
247	export const makeCodexProxyAppLayer = (
248	  configLayer = CodexProxyConfigLive,
249	  liveProxyLayer = CodexProxyOpenAICompatibleProxyLiveOrUnavailable,
250	  makeLocalProxyLayer = makeCodexProxyOpenAICompatibleProxyLocal
251	) =>
252	  Layer.mergeAll(
253	    makeCodexProxyModeLayer(liveProxyLayer, makeLocalProxyLayer),
254	    CodexProxyRoutesLive
255	  ).pipe(Layer.provideMerge(configLayer));
256	
257	export const CodexProxyAppLive = makeCodexProxyAppLayer();
258	
259	export const makeCodexProxyWebHandler = (appLayer = CodexProxyAppLive) =>
260	  HttpRouter.toWebHandler(appLayer, {
261	    disableLogger: true,
262	  });
263	
264	export const codexProxyWebHandler = makeCodexProxyWebHandler();

