  1	import { Context, Effect, Redacted, Schema, Stream } from "effect";
  2	import { HttpClient, HttpClientRequest } from "effect/unstable/http";
  3	
  4	import { codexResponsesEndpointConfig } from "./config.js";
  5	import {
  6	  CodexResponsesProofResult,
  7	  CodexResponsesRequest,
  8	  CodexResponsesStreamEvent,
  9	  CodexResponsesStreamMetadata,
 10	} from "./contracts.js";
 11	import type {
 12	  CodexResponsesPostInput,
 13	  CodexResponsesProofResult as CodexResponsesProofResultType,
 14	  CodexResponsesStreamResult,
 15	} from "./contracts.js";
 16	import {
 17	  CodexHttpNetworkError,
 18	  CodexHttpStatusError,
 19	  CodexResponsesRequestError,
 20	  CodexResponsesStreamError,
 21	} from "./errors.js";
 22	
 23	export type CodexHttpClientFailure =
 24	  | CodexResponsesRequestError
 25	  | CodexHttpNetworkError
 26	  | CodexHttpStatusError
 27	  | CodexResponsesStreamError;
 28	
 29	export interface CodexHttpClientShape {
 30	  readonly postResponses: (
 31	    input: CodexResponsesPostInput
 32	  ) => Effect.Effect<CodexResponsesProofResultType, CodexHttpClientFailure>;
 33	  readonly postResponsesStream: (
 34	    input: CodexResponsesPostInput
 35	  ) => Effect.Effect<CodexResponsesStreamResult, CodexHttpClientFailure>;
 36	}
 37	
 38	export class CodexHttpClient extends Context.Service<
 39	  CodexHttpClient,
 40	  CodexHttpClientShape
 41	>()("@bundjil/codex/CodexHttpClient") {}
 42	
 43	export const makeCodexHttpClient = Effect.gen(function* makeCodexHttpClient() {
 44	  const client = yield* HttpClient.HttpClient;
 45	  const endpoint = yield* codexResponsesEndpointConfig;
 46	
 47	  return CodexHttpClient.of({
 48	    postResponses: Effect.fn("CodexHttpClient.postResponses")(function* (
 49	      input: CodexResponsesPostInput
 50	    ) {
 51	      const encodedRequestBody = yield* Schema.encodeEffect(
 52	        Schema.fromJsonString(CodexResponsesRequest)
 53	      )(input.request).pipe(
 54	        Effect.mapError(
 55	          () =>
 56	            new CodexResponsesRequestError({
 57	              boundary: "CodexResponsesRequest",
 58	              message: "Unable to encode Codex Responses request.",
 59	            })
 60	        )
 61	      );
 62	      const headers = new Headers({
 63	        Authorization: `Bearer ${Redacted.value(input.accessToken)}`,
 64	        "Content-Type": "application/json",
 65	      });
 66	
 67	      if (input.accountId !== undefined) {
 68	        headers.set("chatgpt-account-id", Redacted.value(input.accountId));
 69	      }
 70	
 71	      const upstreamRequest = HttpClientRequest.post(endpoint).pipe(
 72	        HttpClientRequest.setHeaders(headers),
 73	        HttpClientRequest.bodyText(encodedRequestBody, "application/json")
 74	      );
 75	      const response = yield* client.execute(upstreamRequest).pipe(
 76	        Effect.mapError(
 77	          () =>
 78	            new CodexHttpNetworkError({
 79	              operation: "fetch",
 80	              message: "Unable to reach Codex Responses endpoint.",
 81	            })
 82	        )
 83	      );
 84	      const contentType = response.headers["content-type"] ?? "";
 85	
 86	      if (response.status < 200 || response.status >= 300) {
 87	        return yield* new CodexHttpStatusError({
 88	          operation: "postResponses",
 89	          status: response.status,
 90	          statusText: "",
 91	          contentType,
 92	          message: "Codex Responses endpoint returned an unsuccessful status.",
 93	        });
 94	      }
 95	
 96	      const body = yield* response.text.pipe(
 97	        Effect.mapError(
 98	          () =>
 99	            new CodexResponsesStreamError({
100	              operation: "readResponseBody",
101	              message: "Unable to read Codex Responses body.",
102	            })
103	        )
104	      );
105	      if (!contentType.toLowerCase().includes("text/event-stream")) {
106	        return yield* new CodexResponsesStreamError({
107	          operation: "postResponses",
108	          message: "Codex Responses proof requires an SSE response.",
109	        });
110	      }
111	
112	      let receivedStreamLines = 0;
113	      let completed = false;
114	      for (const line of body.split(/\r?\n/)) {
115	        if (!line.startsWith("data:")) {
116	          continue;
117	        }
118	        const data = line.startsWith("data: ")
119	          ? line.slice("data: ".length)
120	          : line.slice("data:".length);
121	        if (data.length === 0 || data === "[DONE]") {
122	          continue;
123	        }
124	
125	        const event = yield* Schema.decodeUnknownEffect(
126	          Schema.fromJsonString(CodexResponsesStreamEvent)
127	        )(data).pipe(
128	          Effect.mapError(
129	            () =>
130	              new CodexResponsesStreamError({
131	                operation: "postResponses",
132	                message: "Unable to decode Codex Responses proof event.",
133	              })
134	          )
135	        );
136	        receivedStreamLines += 1;
137	        completed ||= event.type === "response.completed";
138	      }
139	
140	      if (!completed) {
141	        return yield* new CodexResponsesStreamError({
142	          operation: "postResponses",
143	          message: "Codex Responses proof stream did not complete.",
144	        });
145	      }
146	
147	      return yield* Schema.decodeUnknownEffect(CodexResponsesProofResult)({
148	        transport: "direct-codex-responses",
149	        endpoint,
150	        status: response.status,
151	        contentType,
