 87	        agentDeploymentId: candidateAgent.deploymentId,
 88	        stableProxyDeploymentId: previousProxy.deploymentId,
 89	        stableAgentDeploymentId: previousAgent.deploymentId,
 90	        rollbackReady: true,
 91	      } satisfies AutomaticProductionReceipt;
 92	    }
 93	
 94	    const rollbackEligibility = yield* Ref.make<{
 95	      readonly agent: boolean;
 96	      readonly proxy: boolean;
 97	    }>({ agent: false, proxy: false });
 98	    const promote = Effect.gen(function* () {
 99	      yield* Ref.update(rollbackEligibility, (current) => ({
100	        ...current,
101	        proxy: true,
102	      }));
103	      yield* deployments.promote(candidateProxy);
104	      yield* validateCandidate(
105	        yield* deployments.current("proxy"),
106	        candidateProxy,
107	        sourceSha
108	      );
109	      yield* Ref.update(rollbackEligibility, (current) => ({
110	        ...current,
111	        agent: true,
112	      }));
113	      yield* deployments.promote(candidateAgent);
114	      yield* validateCandidate(
115	        yield* deployments.current("agent"),
116	        candidateAgent,
117	        sourceSha
118	      );
119	      yield* deployments.probeProxyHealth;
120	    });
121	
122	    yield* promote.pipe(
123	      Effect.onExit((promoteExit) => {
124	        if (Exit.isSuccess(promoteExit)) {
125	          return Effect.void;
126	        }
127	        const rollback = Effect.gen(function* () {
128	          const eligible = yield* Ref.get(rollbackEligibility);
129	          if (eligible.agent) {
130	            yield* deployments.rollback(previousAgent);
131	            yield* validateCandidate(
132	              yield* deployments.current("agent"),
133	              previousAgent,
134	              previousAgent.sourceSha
135	            );
136	          }
137	          if (eligible.proxy) {
138	            yield* deployments.rollback(previousProxy);
139	            yield* validateCandidate(
140	              yield* deployments.current("proxy"),
141	              previousProxy,
142	              previousProxy.sourceSha
143	            );
144	          }
145	        });
146	        return Effect.exit(rollback).pipe(
147	          Effect.flatMap((rollbackExit) =>
148	            Exit.isFailure(rollbackExit)
149	              ? Effect.fail(
150	                  new ProductionDeploymentError({
151	                    operation: "rollback",
152	                    project: null,
153	                    reason: "rollbackFailed",
154	                    retry: "after-readback",
155	                  })
156	                )
157	              : Effect.void
158	          )
159	        );
160	      })
161	    );
162	
163	    return {
164	      status: "promoted",
165	      sourceSha,
166	      previousProxyDeploymentId: previousProxy.deploymentId,
167	      previousAgentDeploymentId: previousAgent.deploymentId,
168	      proxyDeploymentId: candidateProxy.deploymentId,
169	      agentDeploymentId: candidateAgent.deploymentId,
170	      stableProxyDeploymentId: candidateProxy.deploymentId,
171	      stableAgentDeploymentId: candidateAgent.deploymentId,
172	      rollbackReady: true,
173	    } satisfies AutomaticProductionReceipt;
174	  }
175	);
