 44	const codexResponsesSseLineMaxBytes = 1024 * 1024;
 45	const lineFeed = Uint8Array.of(10);
 46	
 47	type LineAccumulator = Readonly<{
 48	  byteLength: number;
 49	  parts: readonly Uint8Array[];
 50	}>;
 51	
 52	type MapperState = Readonly<{
 53	  functionCallIndexes: HashMap.HashMap<number, number>;
 54	  hasFunctionCall: boolean;
 55	  nextFunctionCallIndex: number;
 56	}>;
 57	
 58	const initialMapperState: MapperState = {
 59	  functionCallIndexes: HashMap.empty(),
 60	  hasFunctionCall: false,
 61	  nextFunctionCallIndex: 0,
 62	};
 63	
 64	const streamError = (message: string) =>
 65	  new CodexResponsesStreamError({
 66	    operation: "toOpenAICompatibleStream",
 67	    message,
 68	  });
 69	
 70	const decodeLine = (parts: readonly Uint8Array[], byteLength: number) =>
 71	  Effect.try({
 72	    try: () => {
 73	      const bytes = new Uint8Array(byteLength);
 74	      let offset = 0;
 75	      for (const part of parts) {
 76	        bytes.set(part, offset);
 77	        offset += part.byteLength;
 78	      }
 79	      const contentLength =
 80	        bytes.at(-1) === 13 ? bytes.byteLength - 1 : bytes.byteLength;
 81	      return new TextDecoder("utf-8", { fatal: true }).decode(
 82	        bytes.subarray(0, contentLength)
 83	      );
 84	    },
 85	    catch: () => streamError("Unable to decode a Codex Responses SSE line."),
 86	  });
 87	
 88	const boundedSseLines = (
 89	  source: Stream.Stream<Uint8Array, CodexResponsesStreamError>
 90	) =>
 91	  source.pipe(
 92	    Stream.concat(Stream.succeed(lineFeed)),
 93	    Stream.mapAccumEffect(
 94	      (): LineAccumulator => ({ byteLength: 0, parts: [] }),
 95	      (state, bytes) =>
 96	        Effect.gen(function* splitSseChunk() {
 97	          const lines: string[] = [];
 98	          let { parts } = state;
 99	          let { byteLength } = state;
100	          let segmentStart = 0;
101	
102	          for (let index = 0; index < bytes.byteLength; index += 1) {
103	            if (bytes[index] !== 10) {
104	              continue;
105	            }
106	            const segment = bytes.subarray(segmentStart, index);
107	            const completeLineBytes = byteLength + segment.byteLength;
108	            if (completeLineBytes > codexResponsesSseLineMaxBytes) {
109	              return yield* streamError(
110	                "Codex Responses SSE line exceeded the configured byte limit."
111	              );
112	            }
113	            lines.push(
114	              yield* decodeLine([...parts, segment], completeLineBytes)
115	            );
116	            parts = [];
117	            byteLength = 0;
118	            segmentStart = index + 1;
119	          }
120	
121	          if (segmentStart < bytes.byteLength) {
122	            const residual = bytes.subarray(segmentStart);
123	            byteLength += residual.byteLength;
124	            if (byteLength > codexResponsesSseLineMaxBytes) {
125	              return yield* streamError(
126	                "Codex Responses SSE line exceeded the configured byte limit."
127	              );
128	            }
129	            parts = [...parts, residual];
130	          }
131	
132	          return [{ byteLength, parts }, lines] as const;
133	        })
