208	              chunk(completionId, model, { content: event.delta })
209	            ).pipe(Effect.map(Option.some))
210	      ),
211	      Match.when("response.output_item.added", () =>
212	        Effect.gen(function* mapFunctionCallOutputItem() {
213	          const item = yield* Schema.decodeUnknownEffect(
214	            CodexResponsesOutputItemDiscriminator
215	          )(event.item).pipe(
216	            Effect.mapError(() =>
217	              streamError("Unable to decode Codex Responses output item.")
218	            )
