238	              functionCallIndex
239	            ),
240	            hasFunctionCall: true,
241	            nextFunctionCallIndex: functionCallIndex + 1,
242	          });
243	
244	          return Option.some(
245	            yield* encodeChunk(
246	              chunk(completionId, model, {
247	                tool_calls: [
248	                  {
