275	            functionArguments.output_index
276	          );
277	
278	          if (Option.isNone(functionCallIndex)) {
279	            return yield* streamError(
280	              "Codex function-call arguments arrived before their output item."
281	            );
282	          }
283	
284	          yield* Ref.set(state, { ...current, hasFunctionCall: true });
285	          return Option.some(
286	            yield* encodeChunk(
287	              chunk(completionId, model, {
288	                tool_calls: [
289	                  {
290	                    index: functionCallIndex.value,
291	                    function: { arguments: functionArguments.delta },
292	                  },
293	                ],
294	              })
295	            )
296	          );
297	        })
298	      ),
